#!/usr/bin/env python3
"""Generates port/font_data.h: a stand-in for the NumWorks firmware fonts (fixed cells: small 7x14,
large 10x18), ASCII 32..126, 1 bit per pixel, rows padded to whole bytes. Only used by
eadk_display_draw_string, which NumPlay's own text engine rarely needs. Needs Pillow."""
import sys
from PIL import Image, ImageDraw, ImageFont

def cells(cw, ch, size):
    f = ImageFont.load_default(size)
    out = []
    for c in range(32, 127):
        im = Image.new("L", (cw, ch), 0)
        d = ImageDraw.Draw(im)
        w = d.textlength(chr(c), font=f)
        d.text(((cw - w) / 2, (ch - size) / 2 - 1), chr(c), font=f, fill=255)
        rows = []
        for y in range(ch):
            bits = [1 if im.getpixel((x, y)) >= 110 else 0 for x in range(cw)]
            for b in range(0, cw, 8):
                v = 0
                for i in range(8):
                    v = v << 1 | (bits[b + i] if b + i < cw else 0)
                rows.append(v)
        out.append(rows)
    return out

def emit(name, cw, ch, size):
    g = cells(cw, ch, size)
    s = f"static const uint8_t {name}[] = {{\n"
    for rows in g:
        s += "  " + ",".join(f"0x{v:02x}" for v in rows) + ",\n"
    return s + "};\n"

out = ["/* Generated by tools/genfont.py: do not edit. */", "#include <stdint.h>",
       "#define NP_SMALL_W 7", "#define NP_SMALL_H 14", "#define NP_LARGE_W 10", "#define NP_LARGE_H 18"]
out.append(emit("np_font_small", 7, 14, 10))
out.append(emit("np_font_large", 10, 18, 14))
open(sys.argv[1] if len(sys.argv) > 1 else "port/font_data.h", "w").write("\n".join(out))
